/**
 * The shared boat classes of an ejected project (ADR 0110 D1, D2 as amended after B524; ADR 0112
 * D3; B537b), copied from the runtime's `registry/boat/MsmBoats` and `client/boat/BoatRenderers`:
 * the runtime's parsed `ItemDefinition` is replaced by the plain values the generated `ModItems`
 * passes (`raft`, the chest boat's id or `null`, the wood, the tab or `null`) and a factory making
 * the item for the boat's entity type, `Optional` arguments by `null`, the runtime's registrar
 * lists by the logger, and the `EntityRendererRegistration` seam by vanilla's `EntityRenderers`
 * (widened by Fabric API). No class of our own drives a boat: vanilla's `Boat`, `Raft`,
 * `ChestBoat`, `ChestRaft`, `BoatItem`, `BoatDispenseItemBehavior`, `BoatRenderer` and
 * `RaftRenderer` do. The targets tests compare the code lines with the runtime sources.
 *
 * Minecraft 26.3, Mojang names.
 *
 * @packageDocumentation
 */

import { javaString } from '../java';

/** `boat/ModBoats.java`: the runtime's `MsmBoats`. */
export function modBoatsJava(boatPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MsmBoats (registry/boat) as a plain class.
package ${boatPackage};

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Function;
import net.fabricmc.fabric.api.creativetab.v1.CreativeModeTabEvents;
import net.minecraft.core.Registry;
import net.minecraft.core.dispenser.BoatDispenseItemBehavior;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.entity.EntityDimensions;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.EntityTypes;
import net.minecraft.world.entity.MobCategory;
import net.minecraft.world.entity.vehicle.boat.AbstractBoat;
import net.minecraft.world.entity.vehicle.boat.Boat;
import net.minecraft.world.entity.vehicle.boat.ChestBoat;
import net.minecraft.world.entity.vehicle.boat.ChestRaft;
import net.minecraft.world.entity.vehicle.boat.Raft;
import net.minecraft.world.item.BoatItem;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.block.DispenserBlock;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Boats and chest boats of project woods (ADR 0110 D1 and its amendment after B524). An item with {@code msm:boat} is
 * vanilla's boat under the item's own id: {@link #itemFor} (called by {@code ModItems} for the item) registers the
 * entity type {@code <item id>} as vanilla's {@link Boat} (or {@link Raft} with {@code raft}) and returns the item that
 * places it; with a chest boat it also registers the companion {@code <wood>_chest_boat} ({@code _chest_raft}) as an
 * item (vanilla's {@link BoatItem}) and an entity type (vanilla's {@link ChestBoat} or {@link ChestRaft}). Sizes,
 * tracking range and update interval are those of vanilla's oak boat, oak chest boat, bamboo raft and bamboo chest raft,
 * read from {@link EntityTypes} at registration. No class of our own drives a boat: paddling, water and ice, the two
 * seats, the chest menu and the drops on breaking are vanilla's.
 *
 * <p>{@link #register} (from the mod initialiser, after every item) gives each boat item and chest boat item vanilla's
 * boat dispenser behaviour ({@link BoatDispenseItemBehavior}), puts the chest boat into the boat's creative tab right
 * after it, and logs the entity types. The client draws them with vanilla's renderer ({@code client.boat.BoatRenderers}).
 */
public final class ModBoats {
    private static final Logger LOGGER = LoggerFactory.getLogger(${javaString(modId)});

    private ModBoats() {}

    /**
     * One project boat as registered.
     *
     * @param itemId     the boat item's id, also its entity type's
     * @param boat       the boat's entity type
     * @param boatItem   the boat item
     * @param chest      the chest boat's entity type, if the boat has one
     * @param chestItem  the chest boat item, if the boat has one
     * @param raft       whether both are rafts (drawn and sized as vanilla's bamboo raft)
     * @param wood       the wood the pictures are named after
     * @param tab        the creative tab of the boat item's definition, if any
     */
    public record Registered(Identifier itemId, EntityType<? extends AbstractBoat> boat, Item boatItem,
            Optional<EntityType<? extends AbstractBoat>> chest, Optional<Item> chestItem, boolean raft, Identifier wood,
            Optional<Identifier> tab) {
        /** The chest boat's id, if the boat has one. */
        public Optional<Identifier> chestId() {
            return chest.map(BuiltInRegistries.ENTITY_TYPE::getKey);
        }
    }

    private static final List<Registered> BOATS = new ArrayList<>();

    /** The boats registered so far, in definition order. */
    public static List<Registered> boats() {
        return List.copyOf(BOATS);
    }

    /** The registered boat whose boat or chest boat entity type is {@code type}, if any. */
    public static Optional<Registered> of(EntityType<?> type) {
        return BOATS.stream().filter(b -> b.boat() == type || b.chest().filter(c -> c == type).isPresent()).findFirst();
    }

    /**
     * The boat item of an item with {@code msm:boat}, its entity type registered and, with a chest boat, the chest boat's
     * item and entity type registered too. The returned item is not registered yet: the caller registers it under
     * {@code id} (as every other item). An entity type id that is taken is an error; a chest boat whose item or entity
     * type id is taken is logged, and the boat comes without it.
     *
     * @param id       the boat item's id
     * @param raft     whether it is a raft
     * @param chestId  the chest boat's id, or {@code null} for none
     * @param wood     the wood its pictures are named after
     * @param tab      the boat item's creative tab, or {@code null}
     * @param factory  makes the boat item for the boat's entity type
     * @throws IllegalStateException when the boat's entity type id is already registered
     */
    public static <I extends Item> I itemFor(Identifier id, boolean raft, Identifier chestId, Identifier wood, Identifier tab,
            Function<EntityType<? extends AbstractBoat>, I> factory) {
        if (BuiltInRegistries.ENTITY_TYPE.containsKey(id)) {
            throw new IllegalStateException("msm:boat: entity type id " + id + " is already registered");
        }
        AtomicReference<Item> boatItem = new AtomicReference<>();
        EntityType<? extends AbstractBoat> boatType = raft
                ? ModBoats.<Raft>type(id, (t, level) -> new Raft(t, level, boatItem::get), EntityTypes.BAMBOO_RAFT)
                : ModBoats.<Boat>type(id, (t, level) -> new Boat(t, level, boatItem::get), EntityTypes.OAK_BOAT);
        I item = factory.apply(boatType);
        boatItem.set(item);

        Optional<EntityType<? extends AbstractBoat>> chestType = Optional.empty();
        Optional<Item> chestItem = Optional.empty();
        if (chestId != null) {
            if (BuiltInRegistries.ITEM.containsKey(chestId) || BuiltInRegistries.ENTITY_TYPE.containsKey(chestId)) {
                LOGGER.error("{}: msm:boat: chest boat id {} is already registered; the boat has no chest boat", id, chestId);
            } else {
                AtomicReference<Item> chestRef = new AtomicReference<>();
                EntityType<? extends AbstractBoat> type = raft
                        ? ModBoats.<ChestRaft>type(chestId, (t, level) -> new ChestRaft(t, level, chestRef::get), EntityTypes.BAMBOO_CHEST_RAFT)
                        : ModBoats.<ChestBoat>type(chestId, (t, level) -> new ChestBoat(t, level, chestRef::get), EntityTypes.OAK_CHEST_BOAT);
                ResourceKey<Item> key = ResourceKey.create(Registries.ITEM, chestId);
                Item chest = Registry.register(BuiltInRegistries.ITEM, key, new BoatItem(type, new Item.Properties().setId(key).stacksTo(1)));
                chestRef.set(chest);
                chestType = Optional.of(type);
                chestItem = Optional.of(chest);
            }
        }
        BOATS.add(new Registered(id, boatType, item, chestType, chestItem, raft, wood, Optional.ofNullable(tab)));
        return item;
    }

    /**
     * The dispenser behaviour of every boat and chest boat item, the chest boats in their boat's creative tab, and a log
     * line with the registered entity types (boats and chest boats).
     */
    public static void register() {
        List<Identifier> ids = new ArrayList<>();
        for (Registered boat : BOATS) {
            if (!BuiltInRegistries.ITEM.containsKey(boat.itemId()) || BuiltInRegistries.ITEM.getValue(boat.itemId()) != boat.boatItem()) {
                continue; // the item itself failed to register
            }
            DispenserBlock.registerBehavior(boat.boatItem(), new BoatDispenseItemBehavior(boat.boat()));
            ids.add(boat.itemId());
            if (boat.chest().isPresent() && boat.chestItem().isPresent()) {
                Item chest = boat.chestItem().get();
                DispenserBlock.registerBehavior(chest, new BoatDispenseItemBehavior(boat.chest().get()));
                ids.add(boat.chestId().orElseThrow());
                // After ModItems' listener for the boat item, so the chest boat comes right after it.
                boat.tab().ifPresent(tab -> CreativeModeTabEvents.modifyOutputEvent(
                        ResourceKey.create(Registries.CREATIVE_MODE_TAB, tab))
                        .register(output -> output.accept(chest)));
            }
        }
        LOGGER.info("registered {} boat type(s)", ids.size());
    }

    private static <T extends AbstractBoat> EntityType<T> type(Identifier id, EntityType.EntityFactory<T> factory, EntityType<?> like) {
        ResourceKey<EntityType<?>> key = ResourceKey.create(Registries.ENTITY_TYPE, id);
        EntityDimensions size = like.getDimensions();
        return Registry.register(BuiltInRegistries.ENTITY_TYPE, key, EntityType.Builder.of(factory, MobCategory.MISC)
                .noLootTable()
                .sized(size.width(), size.height())
                .eyeHeight(size.eyeHeight())
                .clientTrackingRange(like.clientTrackingRange())
                .updateInterval(like.updateInterval())
                .build(key));
    }
}
`;
}

/** `client/boat/BoatRenderers.java`: the runtime's `client/boat/BoatRenderers`. */
export function boatRenderersJava(
  clientPackage: string,
  boatPackage: string,
  modId: string,
): string {
  return `// Generated by MCSuperMods: msm_runtime's BoatRenderers (client/boat) as a plain class.
package ${clientPackage};

import ${boatPackage}.ModBoats;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.fabricmc.fabric.api.client.rendering.v1.ModelLayerRegistry;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.model.geom.ModelLayers;
import net.minecraft.client.model.object.boat.BoatModel;
import net.minecraft.client.model.object.boat.RaftModel;
import net.minecraft.client.renderer.entity.BoatRenderer;
import net.minecraft.client.renderer.entity.EntityRenderers;
import net.minecraft.client.renderer.entity.RaftRenderer;
import net.minecraft.resources.Identifier;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.vehicle.boat.AbstractBoat;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Vanilla's boat renderer for each project boat type, with a model layer and texture of the project's own (ADR 0110 D2
 * and its amendment after B524). Client only.
 *
 * <p>Each boat gets the model layer {@code <wood ns>:boat/<wood path>#main} (a chest boat {@code chest_boat/<wood path>})
 * registered through Fabric's {@code ModelLayerRegistry} with vanilla's boat or raft layer definition, and vanilla's
 * {@link BoatRenderer} (a raft {@link RaftRenderer}) over it. Vanilla's renderer reads the picture named after the layer:
 * {@code <wood ns>:textures/entity/boat/<wood path>.png} (128 x 64) and {@code .../entity/chest_boat/<wood path>.png}
 * (128 x 128). A layer vanilla already knows (a {@code wood_texture} naming a vanilla wood, such as {@code minecraft:oak})
 * is used as it is and not registered again; two project boats of one wood share one layer.
 */
public final class BoatRenderers {
    private static final Logger LOGGER = LoggerFactory.getLogger(${javaString(modId)});

    private BoatRenderers() {}

    /** The layers registered or reused, with whether each is a raft's. */
    private static final Map<ModelLayerLocation, Boolean> LAYERS = new HashMap<>();

    /** Registers the model layers and renderers of every project boat registered by {@link ModBoats}. */
    public static void init() {
        Set<ModelLayerLocation> vanilla = ModelLayers.getKnownLocations().collect(Collectors.toSet());
        for (ModBoats.Registered boat : ModBoats.boats()) {
            renderer(boat.boat(), layer(vanilla, boat.wood(), false, boat.raft()), boat.raft());
            boat.chest().ifPresent(chest -> renderer(chest, layer(vanilla, boat.wood(), true, boat.raft()), boat.raft()));
        }
        if (!ModBoats.boats().isEmpty()) {
            LOGGER.info("boat renderers for {} boat type(s) over {} model layer(s)",
                    ModBoats.boats().stream().mapToInt(b -> b.chest().isPresent() ? 2 : 1).sum(), LAYERS.size());
        }
    }

    /** The model layer of a boat ({@code chest} false) or chest boat of {@code wood}. */
    public static ModelLayerLocation layerOf(Identifier wood, boolean chest) {
        return new ModelLayerLocation(Identifier.fromNamespaceAndPath(wood.getNamespace(), (chest ? "chest_boat/" : "boat/") + wood.getPath()), "main");
    }

    /** Whether vanilla's layer {@code layer} holds a raft's model: vanilla's only rafts are bamboo's. */
    private static boolean vanillaRaft(ModelLayerLocation layer) {
        return layer.model().getPath().endsWith("/bamboo");
    }

    private static ModelLayerLocation layer(Set<ModelLayerLocation> vanilla, Identifier wood, boolean chest, boolean raft) {
        ModelLayerLocation layer = layerOf(wood, chest);
        Boolean known = LAYERS.get(layer);
        if (known == null && vanilla.contains(layer)) {
            known = vanillaRaft(layer);
            LAYERS.put(layer, known);
        }
        if (known == null) {
            ModelLayerRegistry.registerModelLayer(layer, raft
                    ? (chest ? RaftModel::createChestRaftModel : RaftModel::createRaftModel)
                    : (chest ? BoatModel::createChestBoatModel : BoatModel::createBoatModel));
            LAYERS.put(layer, raft);
        } else if (known != raft) {
            LOGGER.warn("model layer {} holds a {} model but a {} uses it; it is drawn with that model",
                    layer, known ? "raft" : "boat", raft ? "raft" : "boat");
        }
        return layer;
    }

    /** Vanilla's renderer for the layer's model: a raft's renderer for a raft layer, else the boat renderer. */
    private static void renderer(EntityType<? extends AbstractBoat> type, ModelLayerLocation layer, boolean raft) {
        boolean raftModel = LAYERS.getOrDefault(layer, raft);
        if (raftModel) {
            EntityRenderers.<AbstractBoat>register(type, context -> new RaftRenderer(context, layer));
        } else {
            EntityRenderers.<AbstractBoat>register(type, context -> new BoatRenderer(context, layer));
        }
    }
}
`;
}
